def regex_substitute(target_str: str, pattern: str, replace_str: str, index: int = 0) -> str:
    """
    Performs a regular expression substitution on a string using the pyAether engine.

    This function encapsulates the necessary steps to compile a regex pattern and then
    replace occurrences of that pattern in the target string.

    Args:
        target_str (str): The original string to be processed.
        pattern (str): The regular expression pattern to match.
        replace_str (str): The string to use as a replacement.
        index (int, optional): Specifies which occurrence of the matched substring to replace.
