    Returns:
        str: The modified string with substitutions applied, or the original string if no match is found.
    """
    try:
        regex = pyScript.compile_regex(pattern)
        if index <= 0:
            return regex.sub(replace_str, target_str)
        else:
            return regex.sub(replace_str, target_str, count=index)
    except Exception:
